from pathlib import Path
from PIL import Image
import io,base64
R=Path(__file__).resolve().parents[1];out=R.parent/'game-assets'
materials=[('metal-ingot','Слитки','Общий металл · также детали оружия'),('leather','Кожа','Выделанная кожа и шкура'),('copper-block','Медный блок','Металлическая поверхность и окисление'),('raw-meat','Сырое мясо','Отдельная поверхность еды'),('cooked-meat','Жареное мясо','Отдельная прожаренная поверхность'),('water','Вода','Материал ряби · не кадр водного шейдера'),('lava','Лава','Корка и горячие трещины'),('cat-fur','Шерсть кота','Отдельный материал новой модели')]
cards=[]
for n,title,note in materials:
 im=Image.open(R/f'Assets/Art/PBR/{n}_albedo.jpg').convert('RGB').resize((320,320));b=io.BytesIO();im.save(b,'WEBP',quality=85,method=6);src='data:image/webp;base64,'+base64.b64encode(b.getvalue()).decode()
 cards.append(f'<article><img src="{src}" alt="{title}"><div><h2>{title}</h2><p>{note}</p><small>512px · albedo / normal / mask</small></div></article>')
page='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LestingCraft — новые материалы</title><style>*{box-sizing:border-box}body{margin:0;background:#111b20;color:#e6eee9;font:16px system-ui,sans-serif}header,main,footer,section{max-width:1120px;margin:auto;padding:24px}header{padding-top:46px}small{color:#a5b7b8}header small{letter-spacing:.17em;color:#d4b97f}h1{font-size:clamp(32px,6vw,62px);font-weight:650;letter-spacing:-.04em;margin:15px 0}header p,footer{line-height:1.65;color:#aebfc1}.badge{display:inline-block;padding:7px 12px;border:1px solid #647a70;border-radius:30px;color:#c7dac8;font-size:12px}main{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}article{overflow:hidden;border:1px solid #34464b;border-radius:12px;background:#1a2a30}article img{display:block;width:100%;aspect-ratio:1;object-fit:cover}article div{padding:16px}h2{font-size:19px;margin:0 0 8px}article p{font-size:13px;color:#a8bbbd;min-height:36px}article small{font-size:11px;color:#c9b180}section{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}section div{border-top:1px solid #6e8a7d;padding-top:15px}h3{margin:0 0 12px;color:#d7d2bc;font-size:17px}section p{font-size:14px;line-height:1.6;color:#aebfc1}b{color:#e5eee7}footer{border-top:1px solid #34464b;font-size:13px;margin-top:25px;margin-bottom:24px}@media(max-width:850px){main{grid-template-columns:repeat(2,1fr)}section{grid-template-columns:1fr}}@media(max-width:480px){header,main,section,footer{padding-left:14px;padding-right:14px}main{gap:9px}article div{padding:11px}h2{font-size:16px}article p{font-size:12px}}</style><header><small>LESTINGCRAFT / NEW ERA</small><h1>Материалы живого мира</h1><span class="badge">8 новых AI-материалов · исходный проект</span><p>Это образцы подключённых текстур, <b>не скриншоты игры и не проверка GPU</b>. Вода в игре использует прозрачный шейдер с отражением, преломлением и поглощением; здесь показан только исходный материал ряби. Для каждой поверхности подготовлены PBR-карты.</p></header><main>'''+''.join(cards)+'''</main><section><div><h3>Физика и повреждения</h3><p>Падающие песок и гравий, выпавшие предметы, плавучесть, течение воды и лавы. Отдельные HP шести частей тела с последствиями для ходьбы, прыжков и работы руками.</p></div><div><h3>Жители и кот</h3><p>В исходниках — жители с дневным поведением, ночным укрытием, рабочими анимациями и обменом. Собственная модель кота: приручение мясом, следование, сидение и сохранение владельца.</p></div><div><h3>Проверено отдельно</h3><p>112 серверных тестов. 20 021 управляемая C#-проверка. Настоящий кооперативный WebSocket-тест и восстановление после перезапуска локального workerd. Старые ландшафты сохранены.</p></div></section><footer><b>Статус:</b> код и материалы обновлены; нового Windows-билда и публичного развёртывания ещё нет. Импорт и GPU-вид воды/лавы/стекла требуют нативного запуска Unity. Новая динамика мира — только для новых миров версии 6. Обновлённый каталог настоящих инвентарных моделей находится рядом: <b>Voxel-objects-catalog.html</b>.</footer></html>'''
(out/'Живой-мир-материалы.html').write_text(page);print('Offline material preview:',len(page.encode()),'bytes; explicitly not game screenshots.')
